import {readData,esc,landGroup,landLabel,colour,sourcesMarkup,sourceItems} from './research-utils.js?v=20261020-revision3';
const Q=[103.8033972877883,1.287595189398704];
const project=([x,y])=>[(x-Q[0])*111320*Math.cos(Q[1]*Math.PI/180),-(y-Q[1])*111320];
function path(geometry){const polygons=geometry.type==='MultiPolygon'?geometry.coordinates:[geometry.coordinates];return polygons.map(poly=>poly.map(ring=>ring.map((p,i)=>`${i?'L':'M'}${project(p).map(v=>v.toFixed(2)).join(' ')}`).join(' ')+'Z').join(' ')).join(' ');}
const numericGpr=value=>typeof value==='number'&&Number.isFinite(value)?String(value):/^\d+(\.\d+)?$/.test(String(value??'').trim())?String(value).trim():'—';
let mapSerial=0;
export function mountPlanning(container,{lang='en',compact=false}={}){
 const serial=++mapSerial,zh=lang==='zh',t=(a,b)=>zh?b:a;let alive=true,features=[],sources=[],selected=656742,layer='land',view=[-360,-275,720,550],drag=null,moved=false;
 container.innerHTML=`<div class="planning-loading" role="status">${t('Opening the planning record…','正在展开规划记录…')}</div>`;
 function selectedCard(){const f=features.find(f=>f.properties.OBJECTID===selected),p=f?.properties??{},isQ=selected===656742;const el=container.querySelector('.planning-detail');if(!el)return;
 el.innerHTML=`<p class="ev-eyebrow">${isQ?t('QUEENSWAY / SELECTED ZONE','QUEENSWAY／选中分区'):t('NEARBY PLANNING ZONE','周边规划分区')}</p><h4>${esc(landLabel(p.LU_DESC,lang))}</h4><dl><div><dt>${t('Gross plot ratio','总容积率')}</dt><dd>${numericGpr(p.GPR)}</dd></div></dl><p class="planning-detail-note">${isQ?t('Queensway’s planning designation combines commerce and housing.','Queensway的规划用途结合商业与住宅。'):t('Land use and gross plot ratio describe the selected planning zone.','土地用途与容积率对应当前选中的规划分区。')}</p><small>${t('Planning record','规划记录')} ${esc(p.OBJECTID??'')} · MP2025</small>${sourcesMarkup(isQ?['P07','P08','P09']:['P07'],sources,lang)}`;
 container.querySelectorAll('[data-zone]').forEach(p=>{p.classList.toggle('is-selected',Number(p.dataset.zone)===selected);});
 const select=container.querySelector('[data-planning-select]');if(select)select.value=String(selected);
 }
 function updateView(){container.querySelector('.planning-svg')?.setAttribute('viewBox',view.join(' '));}
 function reset(){view=[-360,-275,720,550];updateView();}
 function layerView(){container.querySelector('.planning-map').dataset.layer=layer;container.querySelectorAll('[data-planning-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.planningLayer===layer)));}
 function click(e){const b=e.target.closest('button,[data-zone]');if(!b)return;
  if(b.dataset.zone&&!moved){selected=Number(b.dataset.zone);selectedCard();}
  if(b.dataset.planningZoom){const f=Number(b.dataset.planningZoom);const w=Math.max(190,Math.min(1900,view[2]*f));const h=w*550/720;view=[view[0]+(view[2]-w)/2,view[1]+(view[3]-h)/2,w,h];updateView();}
  if(b.hasAttribute('data-planning-reset')){selected=656742;reset();selectedCard();}
  if(b.dataset.planningLayer){layer=b.dataset.planningLayer;layerView();}
 }
 function change(e){if(e.target.matches('[data-planning-select]')){selected=Number(e.target.value);const f=features.find(f=>f.properties.OBJECTID===selected);if(f){const points=f.geometry.coordinates.flat(f.geometry.type==='MultiPolygon'?2:1).map(project),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),w=Math.max(190,(xmax-xmin)*1.4,(ymax-ymin)*1.4*720/550),h=w*550/720;view=[(xmin+xmax-w)/2,(ymin+ymax-h)/2,w,h];updateView();}selectedCard();}}
 function down(e){const svg=e.target.closest('.planning-svg');if(!svg)return;drag={x:e.clientX,y:e.clientY,view:[...view],svg,zone:e.target.closest('[data-zone]')?.dataset.zone};moved=false;svg.setPointerCapture(e.pointerId);}
 function move(e){if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5)moved=true;const rect=drag.svg.getBoundingClientRect();const scale=Math.max(view[2]/rect.width,view[3]/rect.height);view=[drag.view[0]-dx*scale,drag.view[1]-dy*scale,...drag.view.slice(2)];updateView();}
 function up(){if(drag&&!moved&&drag.zone){selected=Number(drag.zone);selectedCard();}drag=null;}
 function key(e){if(!e.target.matches('.planning-svg'))return;const step=view[2]*.08;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')view[0]-=step;if(e.key==='ArrowRight')view[0]+=step;if(e.key==='ArrowUp')view[1]-=step;if(e.key==='ArrowDown')view[1]+=step;updateView();}}
 Promise.all([readData('planning-context.geojson'),readData('planning-queensway.geojson'),readData('research-sources.json'),readData('nearby-osm-buildings.geojson')]).then(([context,q,ss,buildings])=>{
  if(!alive)return;features=[...context.features.filter(f=>f.properties.OBJECTID!==656742),...q.features];sources=sourceItems(ss);
  const groups=[['mixed','Commercial & residential','商业与住宅'],['commercial','Commercial','商业'],['residential','Residential uses','住宅类用途'],['park','Park / open space','公园／开放空间'],['road','Road','道路'],['water','Water','水体'],['other','Other uses','其他用途']];
  container.innerHTML=`<div class="planning-root${compact?' planning-compact':''}"><div class="planning-toolbar"><div class="ev-segment" aria-label="${t('Map layers','地图图层')}"><button data-planning-layer="land" aria-pressed="true">${t('Land use','土地用途')}</button><button data-planning-layer="buildings" aria-pressed="false">${t('Building reference','建筑参照')}</button></div><span>MP2025 · ${t('Updated 27 MAR 2026','更新于2026.03.27')}</span></div><div class="planning-layout"><div class="planning-map" data-layer="land"><svg class="planning-svg" viewBox="${view.join(' ')}" role="img" tabindex="0" aria-label="${t('Official land-use zones around Queensway. Drag to pan, or use arrow keys; select a zone using the list below.','Queensway周边官方土地用途图。可拖动或用方向键平移，并通过下方列表选择分区。')}"><g class="planning-zones">${features.map(f=>`<path data-zone="${f.properties.OBJECTID}" d="${path(f.geometry)}" fill="${colour[landGroup(f.properties.LU_DESC)]}" fill-rule="evenodd" vector-effect="non-scaling-stroke"><title>${esc(landLabel(f.properties.LU_DESC,lang))} / ${f.properties.OBJECTID}</title></path>`).join('')}</g><g class="planning-buildings">${buildings.features.filter(f=>['Polygon','MultiPolygon'].includes(f.geometry.type)).map(f=>`<path d="${path(f.geometry)}" vector-effect="non-scaling-stroke"/>`).join('')}</g><g class="planning-location" pointer-events="none"><circle r="13"/><circle r="3"/><text x="20" y="-13">QUEENSWAY</text></g></svg><div class="planning-north" aria-hidden="true">N<span>↑</span></div><div class="planning-controls"><button data-planning-zoom="0.7" aria-label="${t('Zoom in','放大')}">+</button><button data-planning-zoom="1.4" aria-label="${t('Zoom out','缩小')}">−</button><button data-planning-reset aria-label="${t('Return to Queensway','返回Queensway')}">⌖</button></div><div class="planning-map-caption">${t('Fill: planned use · Outline: selected zone · Dot: address','填色：规划用途 · 轮廓：选中分区 · 点：地址位置')}</div></div><aside class="planning-detail" aria-live="polite"></aside></div><div class="planning-legend">${groups.map(([id,en,cn])=>`<span><i style="background:${colour[id]}"></i>${t(en,cn)}</span>`).join('')}</div><label class="planning-select-label" for="planning-select-${serial}">${t('Select a planning zone','选择规划分区')}<select id="planning-select-${serial}" data-planning-select>${features.map(f=>`<option value="${f.properties.OBJECTID}" ${f.properties.OBJECTID===656742?'selected':''}>${f.properties.OBJECTID===656742?'Queensway · ':''}${esc(landLabel(f.properties.LU_DESC,lang))} · ${f.properties.OBJECTID}</option>`).join('')}</select></label><details class="ev-data-note"><summary>${t('About this map','关于这张地图')}</summary><p>${t('Official MP2025 land-use polygons, retrieved 19 October 2026. Colours identify planning categories; the highlighted boundary marks the selected planning zone. Queensway is designated Commercial & Residential.','MP2025官方土地用途分区，检索于2026年10月19日。颜色区分规划类别，高亮边界标识当前选中的规划分区。Queensway的规划用途为商业与住宅。')}</p><p>${t('Building outlines: OpenStreetMap / ODbL. The SLA OneMap address point locates Queensway. Select neighbouring zones to explore their planning attributes.','建筑轮廓：OpenStreetMap／ODbL。SLA OneMap地址点标识Queensway的位置。选择周边分区可探索相应规划属性。')}</p><a href="https://data.gov.sg/datasets/d_a8c3546b26712e35021f3a681d0353ae/view" target="_blank" rel="noopener">URA · MP2025 ↗</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OSM / ODbL ↗</a></details></div>`;
  selectedCard();container.addEventListener('click',click);container.addEventListener('change',change);container.addEventListener('pointerdown',down);container.addEventListener('pointermove',move);container.addEventListener('pointerup',up);container.addEventListener('pointercancel',up);container.addEventListener('keydown',key);
 }).catch(()=>{if(alive)container.innerHTML=`<p class="ev-error"><a href="https://data.gov.sg/datasets/d_a8c3546b26712e35021f3a681d0353ae/view" target="_blank" rel="noopener">${t('Read the official source','查看官方来源')} ↗</a></p>`;});
 return()=>{alive=false;for(const [name,fn] of [['click',click],['change',change],['pointerdown',down],['pointermove',move],['pointerup',up],['pointercancel',up],['keydown',key]])container.removeEventListener(name,fn);};
}
